<script setup>
import { ref, onMounted, onBeforeUnmount } from 'vue'

// La maquette est dessinée pour 1728 px : on la réduit proportionnellement sur les écrans plus étroits
const scale = ref(1)
const ready = ref(false)
const update = () => { scale.value = Math.min(window.innerWidth, 1728) / 1728 }
onMounted(() => { update(); ready.value = true; window.addEventListener('resize', update) })
onBeforeUnmount(() => window.removeEventListener('resize', update))
</script>

